export type Target = 'openclaw' | 'codex' | 'claude-code' | 'cursor' | 'gemini-cli' | 'djimit-native';
export const TARGETS: Target[] = ['openclaw', 'codex', 'claude-code', 'cursor', 'gemini-cli', 'djimit-native'];
export interface CompiledArtifact { target: Target; files: Record<string, string>; stub?: boolean }

function clamp(s?: string): string { return String(s ?? '').trim(); }

export function compile(profile: Profile, target: Target): CompiledArtifact {
  switch (target) {
    case 'openclaw': return compileOpenClaw(profile);
    case 'codex': return compileCodex(profile);
    case 'claude-code': return { target, files: { [`${profile.id}.md`]: stub(profile, 'Claude Code .md agent') }, stub: true };
    case 'cursor': return { target, files: { [`${profile.id}.mdc`]: stub(profile, 'Cursor .mdc rule') }, stub: true };
    case 'gemini-cli': return { target, files: { 'SKILL.md': stub(profile, 'Gemini CLI SKILL.md') }, stub: true };
    case 'djimit-native': return { target, files: { 'djimit-agent.yaml': `id: ${profile.id}\nname: ${profile.name}\ndivision: ${profile.division}\nmission: ${JSON.stringify(profile.mission)}\nruntime_targets: [${profile.runtime_targets.join(', ')}]\n` } };
  }
}

function compileOpenClaw(p: Profile): CompiledArtifact {
  const soul = `# SOUL — ${p.name}\n\n${clamp(p.persona) || 'Persona not specified.'}\n\n## Mission\n${clamp(p.mission)}\n`;
  const agents = [
    `# AGENTS — ${p.name}`, '', `Division: ${p.division}`, `Source: ${p.source_repo}/${p.source_path}`, '',
    '## Mission', clamp(p.mission), '',
    '## Critical Rules', ...(p.rules.length ? p.rules.map(r => `- ${r}`) : ['- (none)']), '',
    '## Workflow', ...(p.workflows.length ? p.workflows.map(w => `- ${w}`) : ['- (none)']), '',
    '## Deliverables', ...(p.deliverables.length ? p.deliverables.map(d => `- ${d}`) : ['- (none)']), '',
    '## Success Metrics', ...(p.success_metrics.length ? p.success_metrics.map(m => `- ${m}`) : ['- (none)']), '',
    '## Memory Policy', clamp(p.memory_policy) || '(default — retain task-relevant context only)', '',
    '## Tools Required', ...(p.tools_required.length ? p.tools_required.map(t => `- ${t}`) : ['- (none)']), '',
  ].join('\n');
  const identity = `# IDENTITY — ${p.name}\n\nid: ${p.id}\nname: ${p.name}\ndivision: ${p.division}\nruntime_targets: ${p.runtime_targets.join(', ') || '(none)'}\n`;
  return { target: 'openclaw', files: { 'SOUL.md': soul, 'AGENTS.md': agents, 'IDENTITY.md': identity } };
}

function compileCodex(p: Profile): CompiledArtifact {
  const instructions = [
    `You are ${p.name} (${p.division}).`,
    clamp(p.persona) && `Persona: ${p.persona}`,
    `Mission: ${clamp(p.mission)}`,
    p.rules.length && `Rules:\n${p.rules.map(r => `- ${r}`).join('\n')}`,
    p.workflows.length && `Workflow:\n${p.workflows.map(w => `- ${w}`).join('\n')}`,
    p.tools_required.length && `Tools: ${p.tools_required.join(', ')}`,
  ].filter(Boolean).join('\n\n');
  return { target: 'codex', files: { 'agent.toml': `[agent]\nname = ${JSON.stringify(p.name)}\nmodel = "gpt-4o"\ninstructions = ${JSON.stringify(instructions)}\n` } };
}

function stub(p: Profile, label: string): string { return `# ${p.name} — ${label} (F5 stub, not implemented)\n\nMission: ${p.mission}\n`; }
import Database from 'better-sqlite3';

const MIGRATION = `
CREATE TABLE IF NOT EXISTS profiles (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  division TEXT NOT NULL,
  source_repo TEXT NOT NULL,
  source_path TEXT NOT NULL,
  version_hash TEXT NOT NULL,
  document TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS evaluations (
  id TEXT PRIMARY KEY,
  profile_id TEXT NOT NULL REFERENCES profiles(id),
  version_hash TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending','passed','rejected')),
  schema_valid INTEGER NOT NULL,
  overlap_score REAL NOT NULL,
  injection_score INTEGER NOT NULL,
  risk_level TEXT NOT NULL,
  flags TEXT NOT NULL,
  score REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (profile_id, version_hash)
);
CREATE TABLE IF NOT EXISTS activations (
  profile_id TEXT PRIMARY KEY REFERENCES profiles(id),
  status TEXT NOT NULL CHECK (status IN ('draft','active','rejected','deactivated')),
  target TEXT,
  compiled_artifact TEXT,
  activated_at TEXT,
  deactivated_at TEXT
);
CREATE TABLE IF NOT EXISTS audit_ledger (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  profile_id TEXT NOT NULL,
  action TEXT NOT NULL,
  detail TEXT NOT NULL,
  at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS overlaps (
  a TEXT NOT NULL REFERENCES profiles(id),
  b TEXT NOT NULL REFERENCES profiles(id),
  score REAL NOT NULL,
  PRIMARY KEY (a, b)
);
`;

export interface Profile {
  id: string; name: string; division: string; description?: string;
  source_repo: string; source_path: string; version_hash: string;
  persona: string; mission: string;
  rules: string[]; workflows: string[]; deliverables: string[];
  success_metrics: string[]; memory_policy: string;
  tools_required: string[]; runtime_targets: string[];
  risk_profile: { level: string; injection_score: number; overlap_score: number; flags: string[] };
  evaluation_status: 'pending' | 'passed' | 'rejected';
  activation_status: 'draft' | 'active' | 'rejected' | 'deactivated';
}

export interface Evaluation {
  profile_id: string; schema_valid: boolean; schema_errors: string[];
  injection_score: number; injection_flags: string[];
  overlap_score: number; overlap_with: string | null; overlaps: { id: string; score: number }[];
  risk_level: string; flags: string[]; status: 'pending' | 'passed' | 'rejected';
  score?: number;
}

export class CatalogDB {
  private db: Database.Database;
  constructor(path = ':memory:') {
    this.db = new Database(path); this.db.exec(MIGRATION);
    if (!(this.db.prepare('PRAGMA table_info(evaluations)').all() as Array<{name:string}>).some(column => column.name === 'score')) this.db.exec('ALTER TABLE evaluations ADD COLUMN score REAL');
  }
  close() { this.db.close(); }
  transaction<T>(operation: () => T): T { return this.db.transaction(operation)(); }

  private invalidateActivation(profileId: string, reason: string) {
    const changed = this.db.prepare("UPDATE activations SET status='deactivated', deactivated_at=? WHERE profile_id=? AND status='active'").run(new Date().toISOString(), profileId);
    if (changed.changes) this.audit(profileId, 'activation_invalidated', JSON.stringify({reason}));
  }

  upsertProfile(p: Profile) {
    this.transaction(() => {
    const prior = this.getProfile(p.id);
    this.db.prepare(
      `INSERT INTO profiles(id,name,division,source_repo,source_path,version_hash,document)
       VALUES(?,?,?,?,?,?,?)
       ON CONFLICT(id) DO UPDATE SET name=excluded.name, division=excluded.division,
         source_repo=excluded.source_repo, source_path=excluded.source_path,
         version_hash=excluded.version_hash, document=excluded.document`
    ).run(p.id, p.name, p.division, p.source_repo, p.source_path, p.version_hash, JSON.stringify(p));
    if (prior && prior.version_hash !== p.version_hash) this.invalidateActivation(p.id, 'profile_version_changed');
    });
  }
  getProfile(id: string): Profile | null {
    const row: any = this.db.prepare('SELECT document FROM profiles WHERE id=?').get(id);
    return row ? JSON.parse(row.document) : null;
  }
  listProfiles(): Profile[] {
    return (this.db.prepare('SELECT document FROM profiles ORDER BY name').all() as any[])
      .map(r => JSON.parse(r.document));
  }
  setEvaluation(ev: Evaluation, versionHash: string) {
    this.transaction(() => {
    const id = `${ev.profile_id}:${versionHash}`;
    this.db.prepare(
      `INSERT INTO evaluations(id,profile_id,version_hash,status,schema_valid,overlap_score,injection_score,risk_level,flags,score)
       VALUES(?,?,?,?,?,?,?,?,?,?)
       ON CONFLICT(id) DO UPDATE SET status=excluded.status, schema_valid=excluded.schema_valid,
         overlap_score=excluded.overlap_score, injection_score=excluded.injection_score,
         risk_level=excluded.risk_level, flags=excluded.flags, score=excluded.score`
    ).run(id, ev.profile_id, versionHash, ev.status, ev.schema_valid ? 1 : 0, ev.overlap_score, ev.injection_score, ev.risk_level, JSON.stringify(ev.flags), ev.score ?? null);
    if (ev.status !== 'passed' && this.getProfile(ev.profile_id)?.version_hash === versionHash) this.invalidateActivation(ev.profile_id, 'evaluation_not_passed');
    });
  }
  getEvaluation(profileId: string): any {
    const row: any = this.db.prepare(`SELECT * FROM evaluations WHERE profile_id=?
      ORDER BY (version_hash = (SELECT version_hash FROM profiles WHERE id=?)) DESC, rowid DESC LIMIT 1`).get(profileId, profileId);
    if (!row) return null;
    return { ...row, flags: JSON.parse(row.flags), schema_valid: !!row.schema_valid };
  }
  setActivation(profileId: string, status: string, target: string | null, artifact: string | null) {
    const now = new Date().toISOString();
    if (status === 'active') {
      this.db.prepare(
        `INSERT INTO activations(profile_id,status,target,compiled_artifact,activated_at) VALUES(?,?,?,?,?)
         ON CONFLICT(profile_id) DO UPDATE SET status=excluded.status, target=excluded.target,
           compiled_artifact=excluded.compiled_artifact, activated_at=excluded.activated_at, deactivated_at=NULL`
      ).run(profileId, status, target, artifact, now);
    } else {
      this.db.prepare(
        `INSERT INTO activations(profile_id,status) VALUES(?,?)
         ON CONFLICT(profile_id) DO UPDATE SET status=excluded.status, deactivated_at=?`
      ).run(profileId, status, now);
    }
  }
  getActivation(profileId: string): any {
    return this.db.prepare('SELECT * FROM activations WHERE profile_id=?').get(profileId) || null;
  }
  audit(profileId: string, action: string, detail: string) {
    this.db.prepare('INSERT INTO audit_ledger(profile_id,action,detail) VALUES(?,?,?)').run(profileId, action, detail);
  }
  setOverlap(a: string, b: string, score: number) {
    const [x, y] = a < b ? [a, b] : [b, a];
    this.db.prepare('INSERT OR REPLACE INTO overlaps(a,b,score) VALUES(?,?,?)').run(x, y, score);
  }
  replaceOverlaps(profileId: string, overlaps: Array<{ id: string; score: number }>) {
    this.transaction(() => {
      this.db.prepare('DELETE FROM overlaps WHERE a=? OR b=?').run(profileId, profileId);
      for (const overlap of overlaps) this.setOverlap(profileId, overlap.id, overlap.score);
    });
  }
  counts() {
    const q = (s: string) => (this.db.prepare(s).get() as any).n;
    return {
      total: q('SELECT COUNT(*) n FROM profiles'),
      evaluated: q('SELECT COUNT(*) n FROM evaluations e JOIN profiles p ON p.id=e.profile_id AND p.version_hash=e.version_hash'),
      passed: q("SELECT COUNT(*) n FROM evaluations e JOIN profiles p ON p.id=e.profile_id AND p.version_hash=e.version_hash WHERE e.status='passed'"),
      active: q("SELECT COUNT(*) n FROM activations WHERE status='active'"),
      duplicate: q('SELECT COUNT(*) n FROM overlaps WHERE score>=0.85'),
      rejected: q("SELECT COUNT(*) n FROM evaluations e JOIN profiles p ON p.id=e.profile_id AND p.version_hash=e.version_hash WHERE e.status='rejected'"),
    };
  }
}
